-- Generated by npm run db:export. No accounts or financial transactions are seeded.
BEGIN;
CREATE SCHEMA IF NOT EXISTS easygas_private;
SET LOCAL search_path TO easygas_private,pg_catalog;
CREATE TABLE IF NOT EXISTS schema_migrations (version text PRIMARY KEY, applied_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE branches (id text PRIMARY KEY, name text NOT NULL, active boolean NOT NULL DEFAULT true);
CREATE TABLE users (id text PRIMARY KEY, name text NOT NULL, email text NOT NULL UNIQUE, password_hash text NOT NULL, role text NOT NULL CHECK(role IN ('owner','manager','sales','inventory','dispatcher','driver','finance','customer','commercial','administrator')), branch_id text REFERENCES branches(id), active boolean NOT NULL DEFAULT true, verified boolean NOT NULL DEFAULT false, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE sessions (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), expires_at timestamptz NOT NULL, verified_at timestamptz, revoked_at timestamptz);
CREATE TABLE auth_attempts (key text PRIMARY KEY, attempts integer NOT NULL, reset_at timestamptz NOT NULL);
CREATE TABLE products (id text PRIMARY KEY, name text NOT NULL, description text NOT NULL, category text NOT NULL, size_kg numeric, price_kobo bigint CHECK(price_kobo > 0), published boolean NOT NULL DEFAULT false, asset text NOT NULL, safety text NOT NULL DEFAULT 'Keep upright in a ventilated area, away from heat. Installation must be handled by a qualified professional.');
CREATE TABLE inventory (price_kobo bigint CHECK(price_kobo > 0), published boolean NOT NULL DEFAULT false, branch_id text REFERENCES branches(id), product_id text REFERENCES products(id), quantity integer NOT NULL DEFAULT 0 CHECK(quantity >= 0), reserved integer NOT NULL DEFAULT 0 CHECK(reserved >= 0 AND reserved <= quantity), threshold integer NOT NULL DEFAULT 10 CHECK(threshold >= 0), PRIMARY KEY(branch_id,product_id));
CREATE TABLE stock_movements (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branches(id), product_id text NOT NULL REFERENCES products(id), quantity integer NOT NULL, kind text NOT NULL, reason text NOT NULL, actor_id text NOT NULL REFERENCES users(id), reference text UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE setting_definitions (key text PRIMARY KEY, label text NOT NULL, category text NOT NULL, description text NOT NULL, owner_role text NOT NULL, risk integer NOT NULL CHECK(risk BETWEEN 1 AND 4), value_type text NOT NULL, propose_roles jsonb NOT NULL, approve_roles jsonb NOT NULL, view_roles jsonb NOT NULL, required_roles jsonb NOT NULL DEFAULT '[]', minimum numeric, maximum numeric, additional_verification boolean NOT NULL DEFAULT false);
CREATE TABLE settings (key text REFERENCES setting_definitions(key), scope text NOT NULL, value jsonb NOT NULL, version integer NOT NULL DEFAULT 1, changed_at timestamptz NOT NULL DEFAULT now(), PRIMARY KEY(key,scope));
CREATE TABLE change_requests (id text PRIMARY KEY, key text NOT NULL REFERENCES setting_definitions(key), scope text NOT NULL, requester_id text NOT NULL REFERENCES users(id), previous_value jsonb NOT NULL, proposed_value jsonb NOT NULL, base_version integer NOT NULL, reason text NOT NULL, risk integer NOT NULL, revision integer NOT NULL DEFAULT 1, status text NOT NULL, effective_at timestamptz NOT NULL, expires_at timestamptz NOT NULL, rollback_of text, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE approval_decisions (id text PRIMARY KEY, request_id text NOT NULL REFERENCES change_requests(id), revision integer NOT NULL, approver_id text NOT NULL REFERENCES users(id), role text NOT NULL, decision text NOT NULL, reason text NOT NULL, verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(request_id,revision,approver_id));
CREATE TABLE setting_versions (id text PRIMARY KEY, key text NOT NULL, scope text NOT NULL, version integer NOT NULL, previous_value jsonb NOT NULL, value jsonb NOT NULL, request_id text NOT NULL REFERENCES change_requests(id), actor_id text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(key,scope,version));
CREATE TABLE audit_events (id text PRIMARY KEY, actor_id text, action text NOT NULL, target text NOT NULL, outcome text NOT NULL, detail jsonb NOT NULL DEFAULT '{}', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE notifications (id text PRIMARY KEY, user_id text NOT NULL REFERENCES users(id), title text NOT NULL, body text NOT NULL, related_id text, read_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE orders (delivery_code_hash text NOT NULL, delivery_code_expires_at timestamptz NOT NULL, id text PRIMARY KEY, reference text NOT NULL UNIQUE, customer_id text NOT NULL REFERENCES users(id), branch_id text NOT NULL REFERENCES branches(id), status text NOT NULL DEFAULT 'placed', payment_status text NOT NULL DEFAULT 'unpaid', payment_method text NOT NULL, subtotal_kobo bigint NOT NULL CHECK(subtotal_kobo >= 0), delivery_kobo bigint NOT NULL CHECK(delivery_kobo >= 0), total_kobo bigint NOT NULL CHECK(total_kobo = subtotal_kobo + delivery_kobo), address jsonb NOT NULL, delivery_date text NOT NULL, delivery_window text NOT NULL, instructions text NOT NULL DEFAULT '', driver_id text REFERENCES users(id), idempotency_key text NOT NULL, request_hash text NOT NULL, created_at timestamptz NOT NULL DEFAULT now(), UNIQUE(customer_id,idempotency_key));
CREATE TABLE order_items (order_id text REFERENCES orders(id), product_id text REFERENCES products(id), name text NOT NULL, quantity integer NOT NULL CHECK(quantity BETWEEN 1 AND 20), unit_price_kobo bigint NOT NULL CHECK(unit_price_kobo > 0), PRIMARY KEY(order_id,product_id));
CREATE TABLE order_events (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), status text NOT NULL, actor_id text NOT NULL REFERENCES users(id), note text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cash_collections (id text PRIMARY KEY, order_id text NOT NULL UNIQUE REFERENCES orders(id), collector_id text NOT NULL REFERENCES users(id), amount_kobo bigint NOT NULL CHECK(amount_kobo > 0), verified_by text REFERENCES users(id), verified_at timestamptz, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE verified_payments (id text PRIMARY KEY, order_id text NOT NULL REFERENCES orders(id), reference text NOT NULL UNIQUE, amount_kobo bigint NOT NULL CHECK(amount_kobo > 0), method text NOT NULL, verified_by text NOT NULL REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE wallet_entries (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES users(id), amount_kobo bigint NOT NULL CHECK(amount_kobo != 0), kind text NOT NULL, reference text NOT NULL UNIQUE, reversal_of text UNIQUE REFERENCES wallet_entries(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE reward_entries (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES users(id), points integer NOT NULL, reference text NOT NULL UNIQUE, created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE refill_schedules (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES users(id), product_id text NOT NULL REFERENCES products(id), interval_days integer NOT NULL CHECK(interval_days IN (7,14,28,42)), next_date date NOT NULL, status text NOT NULL DEFAULT 'active', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE support_requests (id text PRIMARY KEY, customer_id text NOT NULL REFERENCES users(id), subject text NOT NULL, message text NOT NULL, status text NOT NULL DEFAULT 'open', created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cylinders (id text PRIMARY KEY, branch_id text NOT NULL REFERENCES branches(id), serial text NOT NULL UNIQUE, size_kg numeric NOT NULL CHECK(size_kg > 0), ownership text NOT NULL CHECK(ownership IN ('company','customer','supplier')), status text NOT NULL CHECK(status IN ('filled','empty','damaged','quarantined','inspection_due')), test_due date NOT NULL, customer_id text REFERENCES users(id), created_at timestamptz NOT NULL DEFAULT now());
CREATE TABLE cylinder_events (id text PRIMARY KEY, cylinder_id text NOT NULL REFERENCES cylinders(id), actor_id text NOT NULL REFERENCES users(id), previous_status text, status text NOT NULL, reason text NOT NULL, created_at timestamptz NOT NULL DEFAULT now());
CREATE FUNCTION prevent_record_mutation() RETURNS trigger LANGUAGE plpgsql SET search_path = pg_catalog AS $$ BEGIN RAISE EXCEPTION 'Append-only record'; END; $$;
CREATE TRIGGER audit_immutable BEFORE UPDATE OR DELETE ON audit_events FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TRIGGER decisions_immutable BEFORE UPDATE OR DELETE ON approval_decisions FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TRIGGER versions_immutable BEFORE UPDATE OR DELETE ON setting_versions FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TRIGGER wallet_immutable BEFORE UPDATE OR DELETE ON wallet_entries FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TRIGGER stock_immutable BEFORE UPDATE OR DELETE ON stock_movements FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE TRIGGER payments_immutable BEFORE UPDATE OR DELETE ON verified_payments FOR EACH ROW EXECUTE FUNCTION prevent_record_mutation();
CREATE INDEX orders_customer_idx ON orders(customer_id,created_at DESC);
CREATE INDEX orders_branch_idx ON orders(branch_id,status);
CREATE INDEX notifications_user_idx ON notifications(user_id,created_at DESC);
CREATE INDEX approvals_scope_idx ON change_requests(scope,status);
CREATE INDEX sessions_user_idx ON sessions(user_id);
CREATE INDEX audit_actor_idx ON audit_events(actor_id,created_at DESC);

